
%% MATH 155 - Homework 2, Problem 1
% Median Filtering for Image Denoising
% Norah Lynch
%
% Apply a 3x3 median filter to remove impulse noise.

clear; clc; close all;

%% Load input image
I = imread('HW2Q1_original_image.jpg');

% Convert image to grayscale if necessary
if size(I, 3) == 3
    Igray = rgb2gray(I);
else
    Igray = I;
end

Igray = uint8(Igray);

%% Get image size
[M, N] = size(Igray);

%% Create padded image
% Use replicated boundary values

Ipad = zeros(M+2, N+2, 'uint8');

% Copy original image into center
Ipad(2:M+1, 2:N+1) = Igray;

% Replicate top and bottom rows
Ipad(1, 2:N+1) = Igray(1, :);
Ipad(M+2, 2:N+1) = Igray(M, :);

% Replicate left and right columns
Ipad(2:M+1, 1) = Igray(:, 1);
Ipad(2:M+1, N+2) = Igray(:, N);

% Replicate four corners
Ipad(1, 1) = Igray(1, 1);
Ipad(1, N+2) = Igray(1, N);
Ipad(M+2, 1) = Igray(M, 1);
Ipad(M+2, N+2) = Igray(M, N);

%% Create output image
Ifiltered = zeros(M, N, 'uint8');

%% Apply 3x3 median filter
for i = 1:M
    for j = 1:N

        % Extract 3x3 pixel neighborhood
        window = Ipad(i:i+2, j:j+2);

        % Convert neighborhood into vector
        values = window(:);

        % Compute median pixel intensity
        medianValue = median(values);

        % Assign median to output pixel
        Ifiltered(i,j) = uint8(medianValue);

    end
end

%% Display input and output images
figure('Name', 'Median Filtering'); %[output:5fb74250]

subplot(1,2,1); %[output:5fb74250]
imshow(Igray); %[output:5fb74250]
title('Input Image'); %[output:5fb74250]

subplot(1,2,2); %[output:5fb74250]
imshow(Ifiltered); %[output:5fb74250]
title('Denoised Image Using 3x3 Median Filter'); %[output:5fb74250]

%% Save output images
imwrite(Ifiltered, 'Q1_denoised.png');

% Save comparison figure
exportgraphics(gcf, 'Q1_comparison.png'); %[output:5fb74250]

disp('Median filtering completed.'); %[output:2978e63b]
disp('Output images saved successfully.'); %[output:3522d1b1]


